-- Appli « Les Français sont-ils en sécurité ? », PR S1 : catalogue de la délinquance
-- enregistrée. Dossier de conception de l'appli sécurité, étapes 5 et 6.
-- Seize atteintes de la base départementale du SSMSI, chacune en nombre (FAITS_…) et en
-- taux pour 1 000 habitants ou logements (TAUX_…). Pas de total par famille : le SSMSI
-- déconseille d'additionner des atteintes comptées dans des unités différentes
-- (victimes, infractions, véhicules, mis en cause).

-- Rubrique et familles (tables créées par la migration 026).
INSERT INTO ref.rubrique (code, libelle, chemin, ordre, theme_obligatoire, avec_angles) VALUES
  ('SECURITE', 'Les Français sont-ils en sécurité ?', '/securite', 6, true, false);

INSERT INTO ref.theme (rubrique, code, libelle, ordre) VALUES
  ('SECURITE', 'PERSONNES', 'Atteintes aux personnes', 1),
  ('SECURITE', 'VOLS', 'Vols et cambriolages', 2),
  ('SECURITE', 'BIENS', 'Dégradations et escroqueries', 3),
  ('SECURITE', 'STUPEFIANTS', 'Stupéfiants', 4),
  ('SECURITE', 'ROUTES', 'Routes', 5),
  ('SECURITE', 'RESSENTI', 'Ce que ressentent les Français', 6);

